// AutoTrade, antes:
const binance = require('./binance');
async function decidir(par) { const preco = await binance.preco(par); if (Date.now() - preco.ts > 3000) return { aprovar: false, motivo: 'stale' }; ... }
// depois (invertido):
function criarDecisao({ mercado, relogio }) {
  return async function decidir(par) {
    const preco = await mercado.preco(par);
    if (relogio.agora() - preco.ts > 3000) return { aprovar: false, motivo: 'stale' };
    ...
  };
}
// teste: criarDecisao({ mercado: { preco: async () => ({ ts: 0, valor: 1 }) }, relogio: { agora: () => 5000 } })
